mapper.select:
SELECT CASE #{level} WHEN 'PROVINCE' THEN CONCAT(LEFT(f.adcode, 2), '0000') WHEN 'CITY' THEN CONCAT(LEFT(f.adcode, 4), '00') WHEN 'DISTRICT' THEN f.adcode ELSE CAST(f.id AS CHAR) END AS region_code, CASE #{level} WHEN 'PROVINCE' THEN f.province WHEN 'CITY' THEN f.city WHEN 'DISTRICT' THEN f.district ELSE f.name END AS region_name, AVG(f.longitude) AS lng, AVG(f.latitude) AS lat, COALESCE(SUM(CASE WHEN f.audit_status = 'APPROVED' AND f.frozen = 0 THEN 1 ELSE 0 END), 0) AS approved, COALESCE(SUM(CASE WHEN f.audit_status = 'PENDING' THEN 1 ELSE 0 END), 0) AS pending, COALESCE(SUM(CASE WHEN f.frozen = 1 THEN 1 ELSE 0 END), 0) AS frozen, CASE WHEN #{level} = 'POINT' THEN f.id END AS farm_id, CASE WHEN #{level} = 'POINT' THEN CASE WHEN f.frozen = 1 THEN 'FROZEN' WHEN f.audit_status = 'PENDING' THEN 'PENDING' WHEN f.disabled = 1 THEN 'DISABLED' ELSE 'NORMAL' END END AS farm_status FROM t_farm f JOIN t_category c ON c.id = f.main_category_id WHERE f.deleted = 0 AND f.audit_status IN ('APPROVED', 'PENDING')
AND LEFT(f.adcode, LENGTH(#{parentCode})) = #{parentCode}
AND c.species = #{species}
GROUP BY region_code, region_name, farm_id, farm_status ORDER BY region_code ASC
